-- Repeat-safe normalized Sri Lankan Grade 1-13 academic master data.
CREATE TABLE IF NOT EXISTS education_levels(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name_en VARCHAR(100) NOT NULL,name_ta VARCHAR(100) NOT NULL,name_si VARCHAR(100) NOT NULL,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS grades(id INT AUTO_INCREMENT PRIMARY KEY,level_id INT NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,name_en VARCHAR(100) NOT NULL,name_ta VARCHAR(100) NOT NULL,name_si VARCHAR(100) NOT NULL,grade_number INT,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(level_id) REFERENCES education_levels(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS streams(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,name_en VARCHAR(100) NOT NULL,name_ta VARCHAR(100) NOT NULL,name_si VARCHAR(100) NOT NULL,is_active BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS grade_subjects(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,subject_id INT NOT NULL,medium VARCHAR(10) NOT NULL DEFAULT 'all',sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE,UNIQUE KEY uq_grade_subject_medium(grade_id,subject_id,medium),FOREIGN KEY(grade_id) REFERENCES grades(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_academic_profiles(user_id INT PRIMARY KEY,education_level_id INT,grade_id INT,stream_id INT,medium VARCHAR(10),school_name VARCHAR(255),district VARCHAR(100),guardian_consent BOOLEAN DEFAULT FALSE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(education_level_id) REFERENCES education_levels(id),FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(stream_id) REFERENCES streams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_subjects(user_id INT NOT NULL,subject_id INT NOT NULL,PRIMARY KEY(user_id,subject_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS teacher_grades(user_id INT NOT NULL,grade_id INT NOT NULL,PRIMARY KEY(user_id,grade_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(grade_id) REFERENCES grades(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS teacher_subjects(user_id INT NOT NULL,subject_id INT NOT NULL,PRIMARY KEY(user_id,subject_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB;

-- SQLAlchemy-created tables may not have server-side defaults. Normalize them
-- before repeat-safe seed inserts so an existing empty schema is supported.
UPDATE education_levels SET is_active=TRUE WHERE is_active IS NULL;
UPDATE grades SET is_active=TRUE WHERE is_active IS NULL;
UPDATE streams SET is_active=TRUE WHERE is_active IS NULL;
UPDATE grade_subjects SET is_active=TRUE WHERE is_active IS NULL;
UPDATE subjects SET is_active=TRUE WHERE is_active IS NULL;
ALTER TABLE education_levels MODIFY is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE grades MODIFY is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE streams MODIFY is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE grade_subjects MODIFY is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE subjects MODIFY is_active BOOLEAN NOT NULL DEFAULT TRUE;

INSERT INTO education_levels(code,name_en,name_ta,name_si,sort_order,is_active) VALUES
('PRIMARY','Primary','ஆரம்பக் கல்வி','ප්‍රාථමික',1,TRUE),('JUNIOR','Junior Secondary','கனிஷ்ட இடைநிலை','කනිෂ්ඨ ද්විතීයික',2,TRUE),('OL','G.C.E. O/L','க.பொ.த. சாதாரண தரம்','අ.පො.ස. සාමාන්‍ය පෙළ',3,TRUE),('AL','G.C.E. A/L','க.பொ.த. உயர்தரம்','අ.පො.ස. උසස් පෙළ',4,TRUE),('TEACHER','Teacher','ஆசிரியர்','ගුරු',5,TRUE),('UNIVERSITY','University/College','பல்கலைக்கழகம்/கல்லூரி','විශ්වවිද්‍යාලය/විද්‍යාලය',6,TRUE),('SELF','Self-Learner','சுய கற்பவர்','ස්වයං ඉගෙනුම්කරු',7,TRUE)
ON DUPLICATE KEY UPDATE name_en=VALUES(name_en),name_ta=VALUES(name_ta),name_si=VALUES(name_si),sort_order=VALUES(sort_order),is_active=TRUE;
INSERT INTO grades(level_id,code,name_en,name_ta,name_si,grade_number,sort_order,is_active)
SELECT l.id,CONCAT('GRADE_',n.n),CONCAT('Grade ',n.n),CONCAT('தரம் ',n.n),CONCAT(n.n,' ශ්‍රේණිය'),n.n,n.n,TRUE FROM education_levels l JOIN (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13)n WHERE l.code=CASE WHEN n.n<=5 THEN 'PRIMARY' WHEN n.n<=9 THEN 'JUNIOR' WHEN n.n<=11 THEN 'OL' ELSE 'AL' END ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),name_en=VALUES(name_en),name_ta=VALUES(name_ta),name_si=VALUES(name_si),is_active=TRUE;
INSERT INTO grades(level_id,code,name_en,name_ta,name_si,sort_order,is_active) SELECT id,CONCAT(code,'_GENERAL'),name_en,name_ta,name_si,20,TRUE FROM education_levels WHERE code IN('TEACHER','UNIVERSITY','SELF') ON DUPLICATE KEY UPDATE name_en=VALUES(name_en),is_active=TRUE;
INSERT INTO streams(code,name_en,name_ta,name_si,sort_order,is_active) VALUES
('BIOLOGICAL_SCIENCE','Biological Science','உயிரியல் விஞ்ஞானம்','ජීව විද්‍යා',1,TRUE),('PHYSICAL_SCIENCE','Physical Science','பௌதிக விஞ்ஞானம்','භෞතික විද්‍යා',2,TRUE),('COMMERCE','Commerce','வர்த்தகம்','වාණිජ',3,TRUE),('ARTS','Arts','கலை','කලා',4,TRUE),('ENGINEERING_TECHNOLOGY','Engineering Technology','பொறியியல் தொழில்நுட்பம்','ඉංජිනේරු තාක්ෂණවේදය',5,TRUE),('BIO_SYSTEMS_TECHNOLOGY','Bio Systems Technology','உயிர் முறைமைகள் தொழில்நுட்பம்','ජෛව පද්ධති තාක්ෂණවේදය',6,TRUE),('GENERAL','General/Common Subjects','பொது பாடங்கள்','සාමාන්‍ය විෂයයන්',7,TRUE)
ON DUPLICATE KEY UPDATE name_en=VALUES(name_en),name_ta=VALUES(name_ta),name_si=VALUES(name_si),is_active=TRUE;

