ON DUPLICATE KEY UPDATE name_en=VALUES(name_en),name_ta=VALUES(name_ta),name_si=VALUES(name_si),sort_order=VALUES(sort_order),is_active=TRUE;
INSERT IGNORE INTO grade_subjects(grade_id,subject_id,medium,sort_order,is_active)
SELECT g.id,s.id,'all',s.sort_order,TRUE FROM grades g JOIN education_levels l ON l.id=g.level_id JOIN subjects s ON s.level=l.code WHERE l.code IN('PRIMARY','JUNIOR','OL');
-- Existing A/L subjects apply to both Grades 12 and 13; stream filtering remains in subject_streams.
INSERT IGNORE INTO grade_subjects(grade_id,subject_id,medium,sort_order,is_active) SELECT g.id,s.id,'all',s.sort_order,TRUE FROM grades g JOIN subjects s ON s.level='AL' WHERE g.code IN('GRADE_12','GRADE_13');
